import { MakeLogicType, actions, kea, path, reducers } from 'kea'
import posthog from 'posthog-js'

import { initKeaTests } from '~/test/init'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface persistedSettingLogicValues {
    setting: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface persistedSettingLogicActions {
    setSetting: (setting: string) => {
        setting: string
    }
}

export type persistedSettingLogicType = MakeLogicType<persistedSettingLogicValues, persistedSettingLogicActions>

const persistedSettingLogic = kea<persistedSettingLogicType>([
    path(['lib', 'utils', 'safeStorageEngine', 'persistedSettingLogic']),
    actions({
        setSetting: (setting: string) => ({ setting }),
    }),
    reducers({
        setting: [
            'default',
            { persist: true },
            {
                setSetting: (_, { setting }) => setting,
            },
        ],
    }),
])

describe('safeStorageEngine', () => {
    afterEach(() => {
        jest.restoreAllMocks()
    })

    it('keeps persisted reducers working for the session when storage rejects every write', () => {
        initKeaTests()
        const captureException = jest.spyOn(posthog, 'captureException').mockImplementation(() => undefined)
        jest.spyOn(Storage.prototype, 'setItem').mockImplementation(() => {
            throw new DOMException('The quota has been exceeded.', 'QuotaExceededError')
        })

        const logic = persistedSettingLogic()
        expect(() => logic.mount()).not.toThrow()
        expect(logic.values.setting).toBe('default')

        logic.actions.setSetting('changed')
        logic.unmount()
        const remounted = persistedSettingLogic()
        remounted.mount()

        expect(remounted.values.setting).toBe('changed')
        expect(captureException).toHaveBeenCalledTimes(1)
    })
})
